using System.Net.Mail;using Servicio.RetazoMarket.Business.DTOs.Proveedor;
namespace Servicio.RetazoMarket.Business.Validators;
public static class ProveedorValidator { public static IReadOnlyCollection<string> Validar(CrearProveedorRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.prov_nombre,r.prov_telefono,r.prov_correo,r.prov_direccion,r.prov_estado); public static IReadOnlyCollection<string> Validar(ActualizarProveedorRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.prov_nombre,r.prov_telefono,r.prov_correo,r.prov_direccion,r.prov_estado).ToList();if(r.id_proveedor<=0)e.Insert(0,"El id del proveedor es inválido.");return e;} public static IReadOnlyCollection<string> ValidarFiltro(ProveedorFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");return e;} private static IReadOnlyCollection<string> Campos(string? n,string? t,string? c,string? d,string? s){var e=new List<string>();if(string.IsNullOrWhiteSpace(n)||n.Trim().Length>100)e.Add("El nombre es obligatorio y admite hasta 100 caracteres.");if(string.IsNullOrWhiteSpace(t)||t.Trim().Length!=10||!t.Trim().All(char.IsDigit))e.Add("El teléfono debe contener exactamente 10 dígitos.");if(string.IsNullOrWhiteSpace(c)||c.Trim().Length>100||!Correo(c))e.Add("El correo no es válido.");if(string.IsNullOrWhiteSpace(d)||d.Trim().Length>255)e.Add("La dirección es obligatoria y admite hasta 255 caracteres.");if(s?.Trim().ToUpperInvariant() is not("ACT" or "INA"))e.Add("El estado debe ser ACT o INA.");return e;} private static bool Correo(string c){try{return new MailAddress(c.Trim()).Address==c.Trim();}catch{return false;}} }
